WITH deduped AS (SELECT id, customer_id, store_id, status, amount, discount, shipping_fee FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY channel ORDER BY amount DESC NULLS FIRST, id) AS row_num FROM orders) x WHERE row_num = 1), not_flagged AS (SELECT s.* FROM deduped s WHERE NOT EXISTS (SELECT 1 FROM order_items c WHERE c.order_id = s.id AND c.unit_price BETWEEN 180 AND 390)), kept_keys AS (SELECT status, customer_id FROM not_flagged EXCEPT DISTINCT SELECT status, customer_id FROM orders WHERE shipping_fee < 15), reconciled AS (SELECT s.* FROM not_flagged s INNER JOIN kept_keys k ON s.status = k.status AND s.customer_id = k.customer_id), with_dims AS (SELECT src.id, src.customer_id, src.store_id, src.status, src.discount, c.email, c.country FROM reconciled src INNER JOIN customers c ON src.customer_id = c.id WHERE c.segment != 'Consumer') SELECT d.region, d.city, s.country, COUNT(*) AS cnt, ROUND(AVG(s.discount), 2) AS avg_discount, GROUPING_ID() AS gid FROM with_dims s INNER JOIN stores d ON s.store_id = d.id GROUP BY ROLLUP (d.region, d.city, s.country);
